'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
// Animate the whole disclosure body, including when a click reverses a transition.
const navGroups=$$('.nav-group'),navAnimations=new WeakMap();
function setNavGroup(group,expanded,animate=true){
 if(group.dataset.expanded===String(expanded))return;
 const content=group.querySelector('.nav-content'),summary=group.querySelector('summary');
 const fromHeight=group.open?content.getBoundingClientRect().height:0;
 const fromOpacity=group.open?Number(getComputedStyle(content).opacity):0;
 navAnimations.get(group)?.cancel();
 group.dataset.expanded=String(expanded);
 group.classList.toggle('is-expanded',expanded);
 summary.setAttribute('aria-expanded',String(expanded));
 content.inert=!expanded;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(!animate||reduced||typeof content.animate!=='function'||$('.app').hidden){
  navAnimations.delete(group);group.open=expanded;return;
 }
 group.open=true;
 const toHeight=expanded?content.getBoundingClientRect().height:0;
 const animation=content.animate([
  {height:`${fromHeight}px`,opacity:fromOpacity},
  {height:`${toHeight}px`,opacity:expanded?1:0}
 ],{duration:320,easing:'cubic-bezier(.22,1,.36,1)',fill:'both'});
 navAnimations.set(group,animation);
 animation.onfinish=()=>{
  if(navAnimations.get(group)!==animation)return;
  navAnimations.delete(group);group.open=expanded;animation.cancel();
 };
}
function expandNavGroup(current){current.closest('nav').querySelectorAll('.nav-group').forEach(group=>setNavGroup(group,group===current));}
function initNavigationGroup(group,index,prefix='desktop'){
 group.removeAttribute('name');
 const content=group.querySelector('.nav-content'),summary=group.querySelector('summary');
 content.id=`${prefix}-nav-content-${index}`;
 summary.setAttribute('aria-controls',content.id);
 setNavGroup(group,group.open,false);
 summary.addEventListener('click',event=>{
  event.preventDefault();
  if(group.dataset.expanded==='true')setNavGroup(group,false);
  else expandNavGroup(group);
 });
}
navGroups.forEach((group,index)=>initNavigationGroup(group,index));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const MODULE_STAGES=Object.freeze({phishing:16,claves:5,cifrado:9,privacidad:10,malware:10,redes:10,copias:10});
const fresh=()=>({phish:{},password:false,cipher:false,pre:null,post:null,lessons:{},positions:{},resume:null});
function safeProgress(value){
 const out=fresh();if(!value||typeof value!=='object'||Array.isArray(value))return out;
 if(value.phish&&typeof value.phish==='object')for(const [k,v] of Object.entries(value.phish))if(/^[0-5]$/.test(k)&&typeof v==='boolean')out.phish[k]=v;
 out.password=value.password===true;out.cipher=value.cipher===true;
 for(const key of ['pre','post']){const v=value[key];if(v&&Number.isInteger(v.score)&&v.score>=0&&v.score<=6&&Array.isArray(v.answers)&&v.answers.length===6&&v.answers.every(n=>Number.isInteger(n)&&n>=0&&n<=3))out[key]={score:v.score,answers:v.answers,date:typeof v.date==='string'?v.date.slice(0,35):''};}
 if(value.lessons&&typeof value.lessons==='object')for(const id of ['privacidad','malware','redes','copias']){const record=value.lessons[id];if(record&&typeof record==='object'){out.lessons[id]={};for(const [k,v] of Object.entries(record))if(/^[0-2]$/.test(k)&&Number.isInteger(v)&&v>=0&&v<=3)out.lessons[id][k]=v;}}
 if(value.positions&&typeof value.positions==='object')for(const [id,total] of Object.entries(MODULE_STAGES)){const n=value.positions[id];if(Number.isInteger(n)&&n>=0&&n<total)out.positions[id]=n;}
 const point=value.resume;if(point&&Object.hasOwn(MODULE_STAGES,point.module)&&Number.isInteger(point.stage)&&point.stage>=0&&point.stage<MODULE_STAGES[point.module])out.resume={module:point.module,stage:point.stage};
 return out;
}
let state=fresh(),memoryOnly=true,progressKey=null;
