function save(){if(!CyberAccount.user||CyberEntry.guest)return;try{localStorage.setItem(progressKey,JSON.stringify(state));}catch{memoryOnly=true;toast('No se pudo guardar una copia local.');}CyberAccount.queueSync(state);}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000);}
const coreCompleted=()=>[Object.keys(state.phish).length===6,state.password,state.cipher].filter(Boolean).length;
const completed=()=>coreCompleted()+learningModules.filter(m=>lessonDone(m.id)).length;
const head=(tag,title,desc,badge='')=>`<div class="page-head"><div><div class="eyebrow">${tag}</div><h1>${title}</h1><p>${desc}</p></div>${badge?`<span class="pill">${badge}</span>`:''}</div>`;
const btn=(label,href,cls='')=>`<a class="btn ${cls}" href="#${href}">${label}<span aria-hidden="true">↗</span></a>`;
function catalogModules(){return [
 {id:'phishing',number:'01',icon:'✉',title:'Detecta el phishing',short:'Reconoce mensajes engañosos y toma una decisión antes de hacer clic.',kind:'6 escenarios',color:''},
 {id:'claves',number:'02',icon:'⌘',title:'Protege tus claves',short:'Prueba una contraseña ficticia y descubre cómo hacerla más resistente.',kind:'Práctica interactiva',color:'blue'},
 {id:'cifrado',number:'03',icon:'⌁',title:'Descubre el cifrado',short:'Convierte un mensaje en un secreto y aprende cómo recuperarlo.',kind:'César + AES-GCM',color:'peach'},
 ...learningModules.map(m=>({...m,kind:'Ideas + 3 retos'}))];}
function moduleState(id){
 const done=id==='phishing'?Object.keys(state.phish).length===6:id==='claves'?state.password:id==='cifrado'?state.cipher:lessonDone(id);
 const answered=id==='phishing'?Object.keys(state.phish).length:['claves','cifrado'].includes(id)?0:lessonStats(id).answered;
 const visited=Object.hasOwn(state.positions,id),started=done||visited||answered>0;
 const stage=visited?state.positions[id]:answered?Math.min(MODULE_STAGES[id]-1,3+answered*2):0;
 const percent=done?100:started?Math.min(95,Math.max(1,Math.round((stage+1)/MODULE_STAGES[id]*100))):0;
 return {done,started,stage,percent,status:done?'Completado':started?'En curso':'Sin empezar'};
}
function resumableStage(id,n){if(id==='cifrado'){if(n===3&&!caesarRecord)return 2;if((n===6||n===7)&&!aesBytes)return 5;}return n;}
function resumeTarget(){
 const point=state.resume;
 if(point&&!moduleState(point.module).done)return {...point,stage:resumableStage(point.module,point.stage)};
 const active=catalogModules().find(m=>moduleState(m.id).started&&!moduleState(m.id).done);
 return active?{module:active.id,stage:resumableStage(active.id,state.positions[active.id]??moduleState(active.id).stage)}:null;
}
function recordLearningPosition(id,n){
 if(!Object.hasOwn(MODULE_STAGES,id))return;
 const stage=Math.min(MODULE_STAGES[id]-1,Math.max(0,n));
 if(state.resume?.module===id&&state.resume.stage===stage&&state.positions[id]>=stage)return;
 state.positions[id]=Math.max(state.positions[id]??0,stage);state.resume={module:id,stage};save();
}
function renderModuleCard(m){
 const progress=moduleState(m.id),target=progress.started&&!progress.done?stageUrl(m.id,resumableStage(m.id,state.positions[m.id]??progress.stage)):'#'+m.id;
 return `<article class="module-card"><div class="module-top ${m.color}"><span class="module-icon" aria-hidden="true">${CyberUI.icon(m.id)}</span><span class="module-index">${m.number}</span></div><div class="module-body"><h3>${m.title}</h3><p>${m.short}</p><div class="meta"><span>${m.kind}</span><span class="module-state ${progress.done?'is-complete':progress.started?'is-started':'is-pending'}"><i aria-hidden="true">${progress.done?'✓':progress.started?'◔':'○'}</i> ${progress.status}</span></div><div class="catalog-meter" role="progressbar" aria-label="Avance de ${m.title}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress.percent}"><span style="width:${progress.percent}%"></span></div><small class="catalog-stage">${progress.done?'Actividad completada':progress.started?`Paso ${progress.stage+1} de ${MODULE_STAGES[m.id]}`:'Empieza cuando quieras'} <b>${progress.percent}%</b></small><a class="btn ghost" href="${target}">${progress.done?'Volver a practicar':progress.started?'Continuar módulo':'Abrir módulo'} <span aria-hidden="true">↗</span></a></div></article>`;
}
const moduleCards=()=>catalogModules().slice(0,3).map(renderModuleCard).join('');
function resumeCard(){
 const point=resumeTarget();if(!point)return '';
 const info=catalogModules().find(m=>m.id===point.module),progress=moduleState(point.module);
 return `<section class="home-resume" aria-labelledby="resume-title"><div class="resume-symbol" aria-hidden="true">${CyberUI.icon(info.id)}</div><div class="resume-copy"><span class="eyebrow">RETOMA TU RECORRIDO</span><h2 id="resume-title">${info.title}</h2><p>Paso ${point.stage+1} de ${MODULE_STAGES[point.module]} · ${CyberEntry.guest?'Disponible durante esta sesión':CyberAccount.user?.emailVerified?'Tu avance se sincroniza con tu cuenta':'Copia en este dispositivo; verifica tu correo para activar la nube'}</p></div><a class="btn lime" id="resume-learning" href="${stageUrl(point.module,point.stage)}">Continuar aprendiendo <span aria-hidden="true">→</span></a><div class="resume-meter" aria-hidden="true"><span style="width:${progress.percent}%"></span></div></section>`;
}
