let phishIndex=0;
function strengthValue(v){const n=[...v].length;const common=/(1234|qwerty|password|contrase[nñ]a|admin|abcdef|1111|0000|brayan|cybercript)/i.test(v)||(/^(.)\1+$/u.test(v)&&n>1);let score=n===0?0:n<8?1:n<15?2:n<20?3:4;if(common)score=Math.min(score,1);return {n,common,score};}
function updateStrength(){const v=$('#password').value,{n,common,score}=strengthValue(v);$('#strength').innerHTML=`<div class="row between"><b>${n===0?'Escribe un ejemplo':common?'Evita patrones conocidos':n<15?'Prueba una frase más larga':'Buen punto de partida'}</b><span class="muted">${n} caracteres</span></div><div class="meter"><div style="width:${score*25}%"></div></div><p class="practice-caption">${common?'Cambia las secuencias o palabras fáciles de adivinar.':n<15?'Busca al menos 15 caracteres en esta práctica.':'La valoración es orientativa: no detecta filtraciones ni garantiza seguridad.'}</p>`;$('#complete-password').disabled=n<15||common;}

let cipherMode='cesar';
function caesar(text,shift){return text.replace(/[A-Za-z]/g,c=>{let base=c<='Z'?65:97;return String.fromCharCode((c.charCodeAt(0)-base+shift+26)%26+base);});}
function moduleProgress(stage,total){const percent=Math.round(stage/(total-1)*100);return `<div class="lesson-progress" role="progressbar" aria-label="Progreso del módulo" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}"><div class="lesson-progress-track"><div class="lesson-progress-fill ${percent?'has-progress':''}" style="width:${percent}%"></div></div><strong class="lesson-progress-value">${percent}%</strong></div>`;}
